-2 :root{font-family:Manrope,system-ui,sans-serif;color:#211b18;background:#eee9e1;font-synthesis:none;--ink:#211b18;--rust:#bd4a30;--paper:#f7f3ed;--line:#d9d1c6}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}.hero{min-height:540px;background:#171311;color:#f5eee5;padding:28px clamp(24px,6vw,90px) 68px;position:relative;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}.hero:before{content:"";position:absolute;width:620px;height:620px;border-radius:50%;right:-120px;top:-180px;background:radial-gradient(circle at 45% 50%,#8c3525 0,#5c271e 26%,#281916 58%,transparent 71%);opacity:.78}.hero:after{content:"";position:absolute;right:8%;bottom:15%;width:240px;height:150px;border:1px solid #b8674f55;border-radius:50%;transform:rotate(-18deg);box-shadow:0 0 60px #bb4d2e22 inset}.brand{display:flex;align-items:center;gap:12px;font-weight:600;z-index:1}.brand-mark{width:36px;height:36px;display:grid;place-items:center;border:1px solid #6d5a50;border-radius:50%;font:500 11px DM Mono}.hero-copy{z-index:1;max-width:760px;margin-top:70px}.eyebrow,.step,.unit,.assumption,.status,.model-badge{font:500 11px DM Mono,monospace;text-transform:uppercase;letter-spacing:.1em}.hero .eyebrow{color:#c18f7e}.hero h1{font-size:clamp(52px,8vw,102px);line-height:.86;letter-spacing:-.065em;margin:22px 0 28px;font-weight:500}.hero h1 em{font-family:Newsreader,Georgia,serif;font-weight:500;color:#dd7859}.lede{font-size:16px;line-height:1.6;color:#b9aaa1;max-width:560px}.model-badge{position:absolute;z-index:1;right:clamp(24px,6vw,90px);bottom:48px;color:#ad9f96;border:1px solid #463b36;border-radius:99px;padding:10px 15px}.pulse,.status span{width:7px;height:7px;background:#c75639;display:inline-block;border-radius:50%;margin-right:8px}
+1 :root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#211b18;background:#eee9e1;font-synthesis:none;--ink:#211b18;--rust:#bd4a30;--paper:#f7f3ed;--line:#d9d1c6}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}.hero{min-height:540px;background:#171311;color:#f5eee5;padding:28px clamp(24px,6vw,90px) 68px;position:relative;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}.hero:before{content:"";position:absolute;width:620px;height:620px;border-radius:50%;right:-120px;top:-180px;background:radial-gradient(circle at 45% 50%,#8c3525 0,#5c271e 26%,#281916 58%,transparent 71%);opacity:.78}.hero:after{content:"";position:absolute;right:8%;bottom:15%;width:240px;height:150px;border:1px solid #b8674f55;border-radius:50%;transform:rotate(-18deg);box-shadow:0 0 60px #bb4d2e22 inset}.brand{display:flex;align-items:center;gap:12px;font-weight:600;z-index:1}.brand-mark{width:36px;height:36px;display:grid;place-items:center;border:1px solid #6d5a50;border-radius:50%;font:500 11px DM Mono}.hero-copy{z-index:1;max-width:760px;margin-top:70px}.eyebrow,.step,.unit,.assumption,.status,.model-badge{font:500 11px DM Mono,monospace;text-transform:uppercase;letter-spacing:.1em}.hero .eyebrow{color:#c18f7e}.hero h1{font-size:clamp(52px,8vw,102px);line-height:.86;letter-spacing:-.065em;margin:22px 0 28px;font-weight:500}.hero h1 em{font-family:Newsreader,Georgia,serif;font-weight:500;color:#dd7859}.lede{font-size:16px;line-height:1.6;color:#b9aaa1;max-width:560px}.model-badge{position:absolute;z-index:1;right:clamp(24px,6vw,90px);bottom:48px;color:#ad9f96;border:1px solid #463b36;border-radius:99px;padding:10px 15px}.pulse,.status span{width:7px;height:7px;background:#c75639;display:inline-block;border-radius:50%;margin-right:8px}
 3 main{max-width:1440px;margin:auto}.control-panel,.results{padding:70px clamp(22px,6vw,88px)}.section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:38px}.section-heading>div:first-child{display:flex;align-items:baseline;gap:18px}.step{color:var(--rust)}h2{font-size:32px;letter-spacing:-.04em;margin:0;font-weight:600}.section-heading>p{font-size:12px;color:#776e67;max-width:320px;margin:10px 0}form{display:grid;grid-template-columns:repeat(6,1fr);gap:22px 14px;align-items:end}form>label{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;position:relative}input,select{display:block;width:100%;margin-top:9px;border:1px solid #cfc5b9;background:#f7f3ed;border-radius:2px;padding:14px 12px;color:var(--ink);outline:none;min-height:50px}input:focus,select:focus{border-color:var(--rust);box-shadow:0 0 0 2px #bd4a3020}.unit{float:right;color:#988f87}.toggles{grid-column:span 3;display:flex;gap:22px}.toggle{display:grid;grid-template-columns:40px 1fr;grid-template-rows:auto auto;align-items:center;column-gap:10px;text-transform:none;font-size:12px;letter-spacing:0;cursor:pointer}.toggle input{display:none}.toggle span{grid-row:span 2;width:40px;height:22px;background:#c9c1b7;border-radius:20px;position:relative}.toggle span:after{content:"";position:absolute;width:16px;height:16px;left:3px;top:3px;border-radius:50%;background:white;transition:.2s}.toggle input:checked+span{background:var(--rust)}.toggle input:checked+span:after{transform:translateX(18px)}.toggle small{font-weight:400;color:#8a8179}.run{grid-column:span 2;background:var(--rust);color:white;border:0;min-height:52px;padding:0 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;font-weight:700}.run:hover{background:#a63d27}.cancel{background:transparent;border:1px solid #b4a99c;padding:12px;cursor:pointer}.assumption{grid-column:1/-1;color:#877e76;border-top:1px solid var(--line);padding-top:15px;margin:0}.results{background:var(--paper);border-top:1px solid var(--line)}.status{border:1px solid #d3c9bd;border-radius:99px;padding:9px 14px;color:#716860}.status span{background:#aaa}.status.working span{background:#d17935;animation:pulse 1s infinite}.status.complete span{background:#4c8255}.status.error span{background:#c22}.progress-track{height:2px;background:#dfd7cc;margin:-18px 0 36px}.progress-track i{display:block;width:0;height:100%;background:var(--rust);transition:width .2s}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin-bottom:18px}.metrics article{padding:23px 25px;border-right:1px solid var(--line)}.metrics article:last-child{border:0}.metrics p{font:500 10px DM Mono;text-transform:uppercase;letter-spacing:.09em;color:#7a716a;margin:0 0 12px}.metrics strong{font-size:30px;letter-spacing:-.04em;display:block}.metrics small{font-size:10px;color:#8a8078}.visual-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:18px}.chart-card,.slice-card{background:#fff;border:1px solid var(--line);padding:22px;min-width:0}.card-head{display:flex;justify-content:space-between;align-items:start;gap:15px}.card-head h3{margin:4px 0 10px;font-size:18px}.card-head .eyebrow{margin:0;color:#9a4a35}.legend{display:flex;gap:14px;font-size:10px;color:#766c64}.legend span:before{content:"";display:inline-block;width:12px;height:2px;margin:0 5px 3px 0;background:#333}.legend .cold:before{background:#442b2a}.legend .probe:before{background:#c44f35}.legend .hot:before{background:#c9a982}canvas{display:block;width:100%}#curve,#slice{height:300px}.compare{font-size:10px;color:#988e85;margin:3px 0 0}.slice-card{background:#221b18;color:#f1e9df;border-color:#221b18}.slice-card .eyebrow{color:#d87859}.slice-card #slice-time{font:10px DM Mono;color:#9f9187}.bands{display:flex;flex-wrap:wrap;gap:10px 13px;font-size:9px;color:#b7aaa0}.bands i{display:inline-block;width:8px;height:8px;background:var(--c);border-radius:50%;margin-right:4px}.advanced{border:1px solid var(--line);margin-top:18px;background:#f0ebe4}.advanced summary{cursor:pointer;display:flex;justify-content:space-between;padding:18px 22px;font-size:12px}.advanced summary::marker{display:none}.advanced summary b{color:#7e4132}.advanced div{padding:4px 22px 22px;border-top:1px solid var(--line);display:grid;grid-template-columns:2fr 1fr 2fr;gap:25px;align-items:center}.advanced p{font-size:11px;color:#746b64;line-height:1.5}.advanced strong{font-size:19px}.advanced .warning{color:#8c3928}.honesty{padding:70px clamp(22px,6vw,88px);display:grid;grid-template-columns:auto 1fr auto;gap:28px;background:#e6dfd6;border-top:1px solid #d0c6ba}.honesty div{max-width:790px}.honesty p{color:#675e57;line-height:1.7;font-size:14px}.honesty a{align-self:center;color:var(--ink);text-decoration:none;border-bottom:1px solid;padding:8px 0;font-size:12px}footer{background:#171311;color:#877a72;display:flex;justify-content:space-between;padding:24px clamp(22px,6vw,88px);font:10px DM Mono;text-transform:uppercase;letter-spacing:.08em}@keyframes pulse{50%{opacity:.3}}
 4 @media(max-width:1000px){form{grid-template-columns:repeat(3,1fr)}.toggles{grid-column:span 2}.run{grid-column:span 1}.visual-grid{grid-template-columns:1fr}.hero:before{right:-300px}.advanced div{grid-template-columns:1fr}.metrics strong{font-size:24px}}
 5 @media(max-width:650px){.hero{min-height:600px}.hero h1{font-size:55px}.model-badge{left:24px;right:auto}.section-heading{display:block}.section-heading>p{margin-left:36px}form{grid-template-columns:1fr 1fr}.toggles{grid-column:1/-1;display:grid}.run{grid-column:1/-1}.metrics{grid-template-columns:1fr 1fr}.metrics article:nth-child(2){border-right:0}.metrics article{border-bottom:1px solid var(--line)}.visual-grid{display:block}.slice-card{margin-top:18px}.card-head{display:block}.legend{margin-bottom:8px}.honesty{grid-template-columns:auto 1fr}.honesty a{grid-column:2}footer{display:block;line-height:2}.advanced summary{display:block}.advanced summary b{display:block;margin-top:6px}}

